import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

/** A note on the sheet: the sheet's today when it was added, who added it, and its text. */
interface NoteView {
  id: number;
  addedOn: string;
  addedBy: string;
  text: string;
}

// The sheet's notes, newest first; a blank note is refused.
